import{_ as t,o as e,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2018-12-05 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2018-12-05 :: Ceph Developer Monthly","date":"2018-12-05T00:00:00.000Z","updated":"2018-12-06T00:00:00.000Z","tags":["Ceph","分布式存储","Orchestrator","Python模块","设备故障预测","开源数据集","驱动器故障检测"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-12-05_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2018/2018-12-05_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),r={name:"posts/2018/2018-12-05_-_-_Ceph_Developer_Monthly.md"};function s(p,l,n,_,a,u){return e(),i("div",null,[...l[0]||(l[0]=[o("<p>本次Ceph开发者月度会议主要讨论了以下内容：</p><ol><li><p><strong>Orchestrator更新</strong>：</p><ul><li>讨论了Orchestrator的最新更新情况，并提供了相关链接供参考。</li></ul></li><li><p><strong>Nautilus依赖问题</strong>：</p><ul><li>Nautilus版本引入了新的依赖，包括Python模块，需要解决依赖问题。</li><li>讨论了如何处理这些依赖，包括是否需要创建新的包或进行回滚。</li></ul></li><li><p><strong>Python模块打包</strong>：</p><ul><li>新的Python模块需要打包，可能需要与James进行讨论。</li><li>确定了打包方式和责任分配。</li></ul></li><li><p><strong>设备故障预测模块</strong>：</p><ul><li>讨论了设备故障预测模块的新依赖，需要确定如何处理这些依赖。</li><li>考虑将具有额外依赖的模块打包成单独的包，以避免不必要的安装。</li></ul></li><li><p><strong>数据收集与模型训练</strong>：</p><ul><li>讨论了构建开源故障数据集的必要性，以训练开源模型。</li><li>与Wisconsin大学学生合作，构建API端点并将数据存储到MySQL数据库。</li></ul></li><li><p><strong>磁盘故障检测</strong>：</p><ul><li>讨论了使用driveutil工具检测磁盘故障的方法。</li><li>在实验室集群上部署该工具，以检测磁盘错误。</li></ul></li></ol><p><strong>行动计划</strong>：</p><ol><li>确定处理Nautilus依赖问题的方案。</li><li>与James讨论Python模块打包事宜。</li><li>确定设备故障预测模块的依赖处理方案。</li><li>与Wisconsin大学学生合作，构建开源故障数据集和模型。</li><li>在实验室集群上部署driveutil工具，以检测磁盘故障。</li></ol><p>会议中提到的关键技术包括Ceph、Orchestrator、Nautilus、Python模块、设备故障预测、开源数据集、驱动器故障检测和driveutil工具等。</p>",5)])])}const d=t(r,[["render",s]]);export{c as __pageData,d as default};
